css.vlak:
/* ═══════════════════════════════════════════════════════════════════
   VLAK, a minimal, CSS-first design system.
   https://vlak.dev

   One ink, no accent hue: emphasis comes from weight, size, and
   spacing. Hairline borders, a 204px module grid (184px column +
   20px gutter), sentence case everywhere.

   Layers: vlak.tokens, vlak.base, vlak.type, vlak.components, vlak.touch, vlak.motion.
   Your own unlayered CSS overrides any of it by default.

   GENERATED from the css/ sources. Edit those, then run
   `npm run build:css`. Tokens come from src/tokens.ts.

   Typeface: Inter (SIL OFL 1.1), variable, latin + latin-ext.
   Bundled. System sans is fallback only.
   ═══════════════════════════════════════════════════════════════════ */

/* ── Inter ── SIL OFL 1.1. Variable, latin + latin-ext.
   System sans is fallback only (see body in base.css). */
@font-face{
  font-family:Inter;
  font-style:normal;
  font-weight:100 900;
  font-display:swap;
  src:url("./fonts/inter/InterVariable-latin-ext.woff2") format("woff2");
  unicode-range:U+0100-02BA,U+02BD-02C5,U+02C7-02CC,U+02CE-02D7,U+02DD-02FF,U+0304,U+0308,U+0329,U+1D00-1DBF,U+1E00-1E9F,U+1EF2-1EFF,U+2020,U+20A0-20AB,U+20AD-20C0,U+2113,U+2C60-2C7F,U+A720-A7FF
}
@font-face{
  font-family:Inter;
  font-style:normal;
  font-weight:100 900;
  font-display:swap;
  src:url("./fonts/inter/InterVariable-latin.woff2") format("woff2");
  unicode-range:U+0000-00FF,U+0131,U+0152-0153,U+02BB-02BC,U+02C6,U+02DA,U+02DC,U+0304,U+0308,U+0329,U+2000-206F,U+20AC,U+2122,U+2191,U+2193,U+2212,U+2215,U+FEFF,U+FFFD
}

@layer vlak.tokens, vlak.base, vlak.type, vlak.components, vlak.touch, vlak.motion;

@layer vlak.tokens {
/* ── Tokens ── GENERATED from src/tokens.ts. Do not edit by hand. */
:root {
  --bg: #FAF8F2;                        /* paper */
  --text: #1A1A1A;                      /* ink */
  --text-secondary: #6B6B6B;            /* gray */
  --accent: #1A1A1A;                   /* the "accent" is ink; monochrome */
  --divider: rgba(0,0,0,0.08);
  --divider-subtle: rgba(0,0,0,0.06);
  --table-alt: rgba(0,0,0,0.02);
  --grid-line: rgba(0,0,0,0.04);
  --control-border: rgba(0,0,0,0.42);
  --control-fill: #E4E2DC;
  color-scheme: light;
  --radius-sm: 4px;           /* slight Vlak radius; standalone buttons */
  --radius: var(--radius-sm);              /* alias — buttons, boxes, dialogs share it; cards stay 0 */
  --radius-chrome: 0px;
  --gutter: 20px;
  --pad: 20px;
  /* Concentric: Steve Ruiz innerRadius result. Closed form of the circular-corner fit. Default radius vs --pad is 0. */
  --radius-in: max(0px, calc(var(--radius) - var(--pad)));
  --ease: cubic-bezier(0.3, 0, 0.2, 1);
  --duration-snap: 0.1s;
  --duration: 0.2s;
  --duration-deliberate: 0.4s;
  --duration-confirm: 0.3s;
  /* The hover transition every control shares: fill, edge, ink, opacity. */
  --transition: background-color var(--duration) var(--ease), border-color var(--duration) var(--ease), color var(--duration) var(--ease), opacity var(--duration) var(--ease);
  /* Background column grid: 204px modules (184 column + 20 gutter). */
  --grid-image: linear-gradient(to right,var(--grid-line) 0,var(--grid-line) 1px,transparent 1px,transparent 184px,var(--grid-line) 184px,var(--grid-line) 185px,transparent 185px,transparent 204px);
  --grid-size: 204px;
  --grid-pos: 20px 0;
  --text-scale: 1;
  /* Stacking scale. Native dialog and popover use the top layer instead. */
  --z-raised: 10;
  --z-sticky: 100;
  --z-float: 200;
  --z-overlay: 300;
  --z-toast: 400;
  /* Contract variables a component may set inline: concentric radius and the chart spot color. */
  --rs-out: var(--radius);
  --rs-gap: var(--pad);
  --rs-in: var(--radius-in);
  --rs-chart-spot: var(--text);
  /* Control scale. Every interactive target is at least 44px; phone fields use 16px type. */
  --hit: 2.75rem;
  --control-h: 2.75rem;
  --control-fs: 0.875rem;
  --control-label: 0.75rem;
}
[data-theme="dark"] {
  --bg: #0E0C0A;
  --text: #E8E8E8;
  --text-secondary: #949494;
  --accent: #E8E8E8;
  --divider: rgba(255,255,255,0.10);
  --divider-subtle: rgba(255,255,255,0.07);
  --table-alt: rgba(255,255,255,0.03);
  --grid-line: rgba(255,255,255,0.05);
  --control-border: rgba(255,255,255,0.38);
  --control-fill: #242220;
  color-scheme: dark;
}
/* System dark scheme applies until the page decides with data-theme. */
@media (prefers-color-scheme: dark) {
:root:not([data-theme="light"]) {
  --bg: #0E0C0A;
  --text: #E8E8E8;
  --text-secondary: #949494;
  --accent: #E8E8E8;
  --divider: rgba(255,255,255,0.10);
  --divider-subtle: rgba(255,255,255,0.07);
  --table-alt: rgba(255,255,255,0.03);
  --grid-line: rgba(255,255,255,0.05);
  --control-border: rgba(255,255,255,0.38);
  --control-fill: #242220;
  color-scheme: dark;
}
}
/* Mobile grid (≤480): two fluid columns, three 25px gutters
   (edge · middle · edge). Column width = 50vw − 37.5px; the background
   draws all four column-edge lines and content lives between the outer pair. */
@media(max-width:480px){
  :root{
    --pad:25px;
    --grid-image:linear-gradient(to right,transparent 0,transparent 25px,var(--grid-line) 25px,var(--grid-line) 26px,transparent 26px,transparent calc(50vw - 12.5px),var(--grid-line) calc(50vw - 12.5px),var(--grid-line) calc(50vw - 11.5px),transparent calc(50vw - 11.5px),transparent calc(50vw + 12.5px),var(--grid-line) calc(50vw + 12.5px),var(--grid-line) calc(50vw + 13.5px),transparent calc(50vw + 13.5px),transparent calc(100vw - 26px),var(--grid-line) calc(100vw - 26px),var(--grid-line) calc(100vw - 25px),transparent calc(100vw - 25px));
    --grid-size:100vw;
    --grid-pos:0 0;
  }
}
/* Phone control scale (≤640): keep 44px hits and use 16px type on fields. */
@media(max-width:640px){
  :root{
    --hit:2.75rem;
    --control-h:2.75rem;
    --control-fs:1rem;
    --control-label:0.9375rem;
  }
}

}

@layer vlak.base {
/* ── Base ──
   Vlak owns the page: paper on html, ink on body, and quiet
   gutter verticals on html::before so overflow-x:clip cannot drop
   them. --grid-pos: 20px 0 puts the first tile line on the left
   20px gutter; that utmost left gutter must paint. Do not clip
   it. No 204 horizontals — those cage the type. Homepage and
   About kill this overlay and keep boxed cells only. */
/* --text-scale multiplies the root size, so every rem in the system (type,
   controls, spacing inside components) follows it while the px module grid
   stays put. Browser text settings still apply underneath. */
html{scroll-behavior:smooth;overflow-x:clip;background-color:var(--bg);font-size:calc(100% * var(--text-scale, 1))}
html::before{
  content:"";
  position:fixed;
  inset:0;
  z-index:0;
  pointer-events:none;
  background-image:var(--grid-image);
  background-size:var(--grid-size) 100%;
  background-repeat:repeat-x;
  background-position:var(--grid-pos)
}
body{
  position:relative;
  z-index:1;
  overflow-x:clip;
  background-color:transparent;
  color:var(--text);
  font-family:Inter,-apple-system,BlinkMacSystemFont,'Segoe UI',system-ui,sans-serif;
  font-weight:500;
  line-height:1.45;
  transition:var(--transition);
  -webkit-font-smoothing:antialiased;
}

/* ── Utilities ── */
.rs-sr{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
.rs-sr:focus-visible+.rs-check,.rs-sr:focus-visible+.rs-radio-dot,.rs-sr:focus-visible+.rs-switch{outline:1.5px solid var(--text);outline-offset:2px}

}

@layer vlak.type {
/* ── Type scale ──
   Hierarchy from weight, color, and position; never all caps.
   Sizes are rem: --text-scale on the root scales them with everything else. */
.rs-t-xl{font-size:clamp(2.125rem,5vw,3.25rem);font-weight:600;letter-spacing:-.035em;line-height:1.05;color:var(--text);margin:0;text-wrap:balance}
.rs-t-display{font-size:2.375rem;font-weight:600;letter-spacing:-.03em;line-height:1.15;color:var(--text);margin:0;text-wrap:balance}
.rs-t-title{font-size:1.375rem;font-weight:600;letter-spacing:-.02em;line-height:1.3;color:var(--text);margin:0;text-wrap:balance}
.rs-t-sub{font-size:1.0625rem;font-weight:500;letter-spacing:-.01em;line-height:1.45;color:var(--text-secondary);margin:0;text-wrap:pretty}
.rs-t-body{font-size:0.9375rem;font-weight:500;letter-spacing:-.01em;line-height:1.45;color:var(--text);margin:0;max-width:66ch;text-wrap:pretty}
.rs-t-label{font-size:0.8125rem;font-weight:600;letter-spacing:-.01em;line-height:1.3;color:var(--text);margin:0}

/* ── Inline code ── */
.rs-code{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:.88em;color:var(--text);background:var(--table-alt);padding:1px 5px;border-radius:var(--radius-sm);letter-spacing:0}

}

@layer vlak.components {
/* ── description-list: generated from packages/react/src/components/description-list.tsx ── */
.rs-description-list{margin:0;width:100%;min-width:0;color:var(--text)}
.rs-description-list-row{display:grid;grid-template-columns:minmax(8rem, 1fr) minmax(0, 2fr);gap:0.5rem;padding-block:1rem;border-bottom-width:1px;border-bottom-style:solid;border-bottom-color:var(--divider)}
@media (max-width: 640px){.rs-description-list-row{grid-template-columns:minmax(0, 1fr)}}
.rs-description-list-label{margin:0;color:var(--text-secondary);font-size:0.875rem;line-height:1.45}
.rs-description-list-value{margin:0;min-width:0;overflow-wrap:anywhere;line-height:1.45;font-variant-numeric:tabular-nums}

/* ── metric: generated from packages/react/src/components/metric.tsx ── */
.rs-metric{display:grid;align-content:start;gap:1rem;min-width:0;color:var(--text)}
.rs-metric-label{color:var(--text-secondary);font-size:0.875rem;line-height:1.45;margin:0}
.rs-metric-reading{display:flex;align-items:baseline;gap:0.5rem;min-height:4rem;min-width:0;font-variant-numeric:tabular-nums;line-height:1}
.rs-metric-value{font-size:clamp(2.5rem, 5vw, 4rem);letter-spacing:-0.04em;font-weight:500;overflow-wrap:anywhere}
.rs-metric-unit{font-size:1.125rem;color:var(--text-secondary)}
.rs-metric-detail{margin:0;color:var(--text-secondary);font-size:0.875rem;line-height:1.45}

/* ── activity-timeline: generated from packages/react/src/components/activity-timeline.tsx ── */
.rs-activity-timeline{list-style-type:none;margin:0;padding:0;color:var(--text);width:100%}
.rs-activity-timeline-event{display:grid;grid-template-columns:minmax(7rem, 1fr) minmax(0, 3fr);gap:0.5rem;padding-block:1rem;border-bottom-width:1px;border-bottom-style:solid;border-bottom-color:var(--divider)}
@media (max-width: 640px){.rs-activity-timeline-event{grid-template-columns:minmax(0, 1fr)}}
.rs-activity-timeline-time{color:var(--text-secondary);font-size:0.875rem;font-variant-numeric:tabular-nums;line-height:1.45}
.rs-activity-timeline-title{margin:0;font-weight:600;line-height:1.45}
.rs-activity-timeline-body{margin-block:0.5rem;line-height:1.45;max-width:66ch;overflow-wrap:anywhere}
.rs-activity-timeline-summary{min-height:var(--hit);display:list-item;align-content:center;cursor:pointer;border-radius:var(--radius-sm);outline-color:var(--text);outline-offset:2px}

/* ── code-block: generated from packages/react/src/components/code-block.tsx ── */
.rs-code-block{margin:0;width:100%;min-width:0;border-width:1px;border-style:solid;border-color:var(--divider);color:var(--text);background-color:var(--bg)}
.rs-code-block-header{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:0.5rem;padding:0.75rem;border-bottom-width:1px;border-bottom-style:solid;border-bottom-color:var(--divider)}
.rs-code-block-pre{margin:0;overflow-x:auto;padding:1rem;font-family:ui-monospace, SFMono-Regular, Menlo, monospace;font-size:0.875rem;line-height:1.45;tab-size:2;outline-color:var(--text);outline-offset:-2px}
.rs-code-block-wrap{white-space:pre-wrap;overflow-wrap:anywhere}
.rs-code-block-line{display:block;min-height:1.45em}
.rs-code-block-number{display:inline-block;user-select:none;color:var(--text-secondary);min-width:3ch;margin-inline-end:2ch;text-align:end}
.rs-code-block-status{font-size:0.875rem;color:var(--text-secondary)}

/* ── json-viewer: generated from packages/react/src/components/json-viewer.tsx ── */
.rs-json-viewer{display:grid;gap:1rem;width:100%;min-width:0;color:var(--text)}
.rs-json-viewer-tools{display:flex;flex-wrap:wrap;gap:0.5rem}
.rs-json-viewer-body{padding:1rem;border-width:1px;border-style:solid;border-color:var(--divider);min-width:0;overflow-wrap:anywhere;font-family:ui-monospace, SFMono-Regular, Menlo, monospace;font-size:0.875rem;line-height:1.45}
.rs-json-viewer-summary{min-height:var(--hit);align-content:center;cursor:pointer;border-radius:var(--radius-sm);outline-color:var(--text);outline-offset:2px}
.rs-json-viewer-children{padding-inline-start:1rem}
.rs-json-viewer-value{min-height:2rem;align-content:center;margin:0}
.rs-json-viewer-note{color:var(--text-secondary);font-family:inherit}

/* ── diff-viewer: generated from packages/react/src/components/diff-viewer.tsx ── */
.rs-diff-viewer{width:100%;min-width:0;color:var(--text)}
.rs-diff-viewer-header{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:0.5rem;margin-bottom:1rem}
.rs-diff-viewer-tools{display:flex;flex-wrap:wrap;gap:0.5rem}
.rs-diff-viewer-scroll{overflow-x:auto;border-width:1px;border-style:solid;border-color:var(--divider);outline-color:var(--text);outline-offset:2px}
.rs-diff-viewer-table{width:100%;border-collapse:collapse;font-family:ui-monospace, SFMono-Regular, Menlo, monospace;font-size:0.875rem;line-height:1.45;text-align:start}
.rs-diff-viewer-cell{padding-block:0.25rem;padding-inline:0.75rem;white-space:pre-wrap;overflow-wrap:anywhere;vertical-align:top;text-align:start}
.rs-diff-viewer-change{background-color:var(--control-fill);font-weight:500}
.rs-diff-viewer-number{color:var(--text-secondary);width:3ch;padding-inline:0.5rem;vertical-align:top;font-variant-numeric:tabular-nums;text-align:end}

/* ── error-summary: generated from packages/react/src/components/error-summary.tsx ── */
.rs-error-summary{box-sizing:border-box;min-width:0;border-width:1px;border-style:solid;border-color:var(--control-border);border-radius:var(--radius-sm);padding:1rem;background-color:var(--bg);color:var(--text);outline-color:var(--text);outline-offset:2px}
.rs-error-summary-title{font-size:0.875rem;font-weight:600;margin:0 0 0.25rem;line-height:1.45}
.rs-error-summary-list{margin:0;padding:0;list-style:none}
.rs-error-summary-link{display:inline-flex;align-items:center;min-height:var(--hit);min-width:var(--hit);max-width:100%;font-size:0.875rem;font-weight:400;color:var(--text);text-decoration:underline;text-decoration-thickness:1px;text-underline-offset:0.2em;line-height:1.45;overflow-wrap:anywhere;border-radius:var(--radius-sm);outline-color:var(--text);outline-offset:2px}

/* ── notification-center: generated from packages/react/src/components/notification-center.tsx ── */
.rs-notification-center{color:var(--text);width:100%;min-width:0}
.rs-notification-center-header{display:flex;flex-wrap:wrap;gap:0.75rem;align-items:center;justify-content:space-between}
.rs-notification-center-title{margin:0;font-size:1rem;font-weight:600;line-height:1.45}
.rs-notification-center-list{list-style-type:none;margin:0;padding:0}
.rs-notification-center-item{padding:1rem;border-bottom-width:1px;border-bottom-style:solid;border-bottom-color:var(--divider);overflow-wrap:anywhere}
.rs-notification-center-unread{background-color:var(--control-fill)}
.rs-notification-center-detail{margin-block:0.5rem;color:var(--text);line-height:1.45}
.rs-notification-center-actions{display:flex;flex-wrap:wrap;gap:0.5rem;margin-top:0.75rem}

/* ── task-progress: generated from packages/react/src/components/task-progress.tsx ── */
.rs-task-progress{display:grid;gap:1rem;color:var(--text);min-width:0;width:100%}
.rs-task-progress-title{margin:0;font-size:1rem;font-weight:600;line-height:1.45}
.rs-task-progress-bar{width:100%;height:0.5rem;accent-color:var(--text)}
.rs-task-progress-detail{margin:0;color:var(--text-secondary);font-size:0.875rem;line-height:1.45;font-variant-numeric:tabular-nums}
.rs-task-progress-phases{margin:0;padding-inline-start:1.5rem;line-height:1.45}
.rs-task-progress-phase{padding-block:0.5rem}
.rs-task-progress-actions{display:flex;flex-wrap:wrap;gap:0.5rem}

/* ── connection-status: generated from packages/react/src/components/connection-status.tsx ── */
.rs-connection-status{display:flex;flex-wrap:wrap;align-items:center;gap:0.75rem;color:var(--text);min-width:0}
.rs-connection-status-label{display:inline-flex;align-items:center;gap:0.5rem;line-height:1.45}
.rs-connection-status-detail{color:var(--text-secondary);font-size:0.875rem;line-height:1.45;margin:0}

/* ── tree-view: generated from packages/react/src/components/tree-view.tsx ── */
.rs-tree-view{list-style-type:none;margin:0;padding:0;color:var(--text);min-width:0;width:100%;box-sizing:border-box;font-size:0.875rem;line-height:1.45}
.rs-tree-view-group{list-style-type:none;margin:0;padding-inline-start:1rem;min-width:0;box-sizing:border-box}
.rs-tree-view-item{display:flex;align-items:center;gap:0.25rem;min-height:var(--hit);min-width:var(--hit);width:100%;padding-inline:0.25rem;box-sizing:border-box;border-radius:var(--radius-sm);cursor:pointer;outline-color:var(--text);outline-offset:-2px}
.rs-tree-view-item:focus-visible{outline-width:2px;outline-style:solid}
.rs-tree-view-label{flex:1 1 auto;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.rs-tree-view-selected{background-color:var(--control-fill);font-weight:600}
.rs-tree-view-disabled{color:var(--text-secondary);cursor:not-allowed}
.rs-tree-view-spacer{width:var(--hit);flex-shrink:0}
.rs-tree-view-disclosure{display:inline-flex;align-items:center;justify-content:center;width:var(--hit);height:var(--hit);min-width:var(--hit);min-height:var(--hit);flex-shrink:0;box-sizing:border-box;border-width:0;border-radius:var(--radius-sm);background-color:transparent;color:var(--text);cursor:pointer;padding:0}

/* ── toolbar: generated from packages/react/src/components/toolbar.tsx ── */
.rs-toolbar{display:flex;flex-wrap:wrap;align-items:center;gap:0.5rem;color:var(--text)}
.rs-toolbar-vertical{flex-direction:column;align-items:stretch}
.rs-toolbar-pressed{font-weight:600}

/* ── bottom-navigation: generated from packages/react/src/components/bottom-navigation.tsx ── */
.rs-bottom-navigation{background-color:var(--bg);color:var(--text);border-top-width:1px;border-top-style:solid;border-top-color:var(--divider);padding-bottom:env(safe-area-inset-bottom, 0px)}
.rs-bottom-navigation-list{list-style-type:none;display:grid;grid-auto-flow:column;grid-auto-columns:minmax(0, 1fr);gap:0.25rem;padding:0.5rem;margin:0}
.rs-bottom-navigation-link{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:0.25rem;min-width:var(--hit);min-height:var(--hit);box-sizing:border-box;padding:0.5rem;color:var(--text-secondary);text-decoration:none;font-size:0.875rem;border-radius:var(--radius-sm);text-align:center;overflow-wrap:anywhere;outline-color:var(--text);outline-offset:2px}
.rs-bottom-navigation-current{color:var(--text);font-weight:600;background-color:var(--control-fill)}

/* ── overflow-list: generated from packages/react/src/components/overflow-list.tsx ── */
.rs-overflow-list{position:relative;display:flex;align-items:center;gap:0.5rem;width:100%;min-width:0;color:var(--text)}
.rs-overflow-list-measure{position:absolute;visibility:hidden;pointer-events:none;display:flex;gap:0.5rem;width:max-content;inset-block-start:0;inset-inline-start:0}
.rs-overflow-list-sample{display:inline-flex;align-items:center;justify-content:center;min-width:var(--hit);min-height:var(--hit);box-sizing:border-box;border-width:1px;border-style:solid;padding-inline:1.375rem;font-family:inherit;font-size:var(--control-fs);letter-spacing:-0.01em;white-space:nowrap}
.rs-overflow-list-more{flex-shrink:0;min-width:0}

/* ── filter-bar: generated from packages/react/src/components/filter-bar.tsx ── */
.rs-filter-bar{display:flex;flex-wrap:wrap;align-items:center;gap:0.5rem;color:var(--text);min-width:0}
.rs-filter-bar-count{font-size:0.875rem;color:var(--text-secondary);font-variant-numeric:tabular-nums;line-height:1.45}

