.rs-input:focus{border-color:var(--accent)}
.rs-input:focus-visible{outline-width:2px;outline-style:solid}
.rs-input:-webkit-autofill{-webkit-text-fill-color:var(--text);caret-color:var(--text);background-color:var(--bg);box-shadow:inset 0 0 0 1000px var(--bg)}
@media (max-width: 640px){.rs-input{min-height:var(--hit);border-radius:var(--radius-sm);font-size:1rem;padding-inline:0.875rem}}
.rs-input-grouped{border-width:0;border-radius:0;height:100%;flex-grow:1;min-width:0;background-color:var(--bg);color:var(--text);outline-width:0;outline-style:none}
.rs-input-grouped:focus-visible{outline-width:0;outline-style:none}
@media (max-width: 640px){.rs-input-grouped{min-height:var(--hit)}}
.rs-input-full{width:100%}
.rs-input-ok{border-color:var(--text)}
.rs-input-invalid{border-color:var(--text)}
.rs-feedback{display:flex;align-items:center;gap:0.5rem;font-size:0.75rem;font-weight:500;color:var(--text-secondary);letter-spacing:-0.01em;line-height:16px;margin:0;min-height:1rem}
@media (max-width: 640px){.rs-feedback{font-size:0.875rem}}
