"use client";

import * as React from "react";
import * as stylex from "@stylexjs/stylex";
import { vlak, mq } from "./tokens.stylex";
import { rs } from "./rs";
import { Icon } from "./icons";

export interface InlineFormProps
  extends Omit<React.FormHTMLAttributes<HTMLFormElement>, "onSubmit"> {
  placeholder?: string;
  buttonLabel?: React.ReactNode;
  successLabel?: React.ReactNode;
  pendingLabel?: React.ReactNode;
  errorLabel?: React.ReactNode;
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  /** The action only appears once this returns true. Defaults to a loose e-mail check. */
  validate?: (value: string) => boolean;
  onSubmit?: (value: string) => void | Promise<void>;
  inputProps?: React.InputHTMLAttributes<HTMLInputElement>;
}

const fadeIn = stylex.keyframes({
  from: { opacity: 0 },
  to: { opacity: 1 },
});

const styles = stylex.create({
  field: {
    boxSizing: "border-box",
    display: "flex",
    flexWrap: "wrap",
    alignItems: {
      default: "center",
      [mq.phone]: "stretch",
    },
    gap: "0.5rem",
    width: "100%",
    borderWidth: vlak.hairline,
    borderStyle: "solid",
    borderColor: {
      default: vlak.divider,
      ":focus-within": vlak.accent,
    },
    borderRadius: {
      default: vlak.radiusSm,
      [mq.phone]: vlak.radiusSm,
    },
    backgroundColor: "var(--bg)",
    paddingBlock: {
      default: "0.25rem",
      [mq.phone]: 0,
    },
    paddingInlineStart: {
      default: "0.75rem",
      [mq.phone]: 0,
    },
    paddingInlineEnd: {
      default: "0.375rem",
      [mq.phone]: 0,
    },
    minHeight: {
      default: null,
      [mq.phone]: vlak.hit,
    },
    transition: `border-color ${vlak.durationSnap} ${vlak.ease}`,
  },
  input: {
    boxSizing: "border-box",
    flexGrow: 1,
    minWidth: 0,
    appearance: "none",
    WebkitAppearance: "none",
    borderWidth: 0,
    backgroundColor: "transparent",
    color: "var(--text)",
    caretColor: "var(--text)",
    fontFamily: "inherit",
    fontSize: {
      default: "0.875rem",
      [mq.phone]: "1rem",
    },
    letterSpacing: "-0.01em",
    outline: "none",
    paddingBlock: {
      default: "0.4375rem",
      [mq.phone]: 0,
    },
    paddingInline: {
      default: 0,
      [mq.phone]: "0.875rem",
    },
    minHeight: {
      default: vlak.hit,
      [mq.phone]: vlak.hit,
    },
    "::placeholder": {
      color: vlak.gray,
    },
  },
  reveal: {
    maxWidth: 0,
    opacity: 0,
    overflow: "hidden",
    transition: `max-width ${vlak.duration} ${vlak.ease}, opacity ${vlak.duration} ${vlak.ease}`,
  },
  revealIn: {
    maxWidth: "10rem",
    opacity: 1,
  },
