    },
    height: {
      default: "0.875rem",
      [mq.phone]: "1.375rem",
    },
    borderRadius: {
      default: "50%",
      [mq.phone]: "50%",
    },
    backgroundColor: vlak.paper,
    borderWidth: 1.5,
    borderStyle: "solid",
    borderColor: vlak.ink,
    boxSizing: "border-box",
    pointerEvents: "none",
  },
  /** Keyboard focus on the hidden range paints a ring on the thumb. */
  thumbFocused: {
    outlineWidth: 2,
    outlineStyle: "solid",
    outlineColor: vlak.ink,
    outlineOffset: 2,
  },
  range: {
    position: "absolute",
    insetInlineStart: 0,
    insetInlineEnd: 0,
    // The hit area is 44px; the visible track stays quiet.
    top: {
      default: "-1.3125rem",
      [mq.phone]: "-1.25rem",
    },
    bottom: {
      default: "-1.3125rem",
      [mq.phone]: "-1.25rem",
    },
    width: "100%",
    height: "auto",
    opacity: 0,
    cursor: "pointer",
    margin: 0,
  },
});

function isFocusVisible(el: HTMLElement): boolean {
  try {
    return el.matches(":focus-visible");
  } catch {
    return true;
  }
}

