    },
    borderWidth: 0,
    borderStyle: "solid",
    borderInlineStartWidth: vlak.hairline,
    borderColor: vlak.divider,
    borderStartStartRadius: vlak.radiusSm,
    borderStartEndRadius: 0,
    borderEndEndRadius: 0,
    borderEndStartRadius: vlak.radiusSm,
    paddingBlock: "1.5rem",
    paddingInline: "1.25rem",
    backgroundColor: vlak.paper,
    color: vlak.ink,
    boxShadow: "none",
    "::backdrop": {
      backgroundColor: ["rgba(0,0,0,0.25)", `color-mix(in srgb, ${vlak.paper} 55%, transparent)`],
    },
  },
  left: {
    insetInlineEnd: "auto",
    insetInlineStart: 0,
    borderInlineStartWidth: 0,
    borderInlineEndWidth: vlak.hairline,
    borderStartStartRadius: 0,
    borderStartEndRadius: vlak.radiusSm,
    borderEndEndRadius: vlak.radiusSm,
    borderEndStartRadius: 0,
    boxShadow: "none",
  },
  title: {
    display: "block",
    fontSize: {
      default: "0.9375rem",
      [mq.phone]: "1.125rem",
    },
    fontWeight: 600,
    letterSpacing: "-0.01em",
    color: vlak.ink,
    marginTop: 0,
    marginInlineEnd: 0,
    marginBottom: "0.375rem",
    marginInlineStart: 0,
  },
  body: {
    fontSize: {
      default: "0.84375rem",
      [mq.phone]: "1rem",
    },
    lineHeight: 1.45,
    letterSpacing: "-0.01em",
    color: vlak.gray,
    margin: 0,
  },
});

/**
 * A native <dialog> at the screen edge. The platform provides the
 * focus trap, Escape, and the backdrop; the title names it.
 */
export const Sheet = React.forwardRef<HTMLDialogElement, SheetProps>(function Sheet(
  { open, onClose, dismissable, lightDismiss, closeLabel, side = "right", className, style, children, ...props },
  forwardedRef,
) {
  const { ref, context, dialogProps } = useNativeDialog({ open, onClose, dismissable, lightDismiss }, props, forwardedRef);
  const sx = rs(["rs-sheet", side === "left" && "rs-sheet-left", className], styles.frame, side === "left" && styles.left);
  const close = rs(["rs-sheet-close"], dialogStyles.close);
  return (
    <DialogContext.Provider value={context}>
      <dialog ref={ref} {...props} {...dialogProps} className={sx.className} style={{ ...sx.style, ...style }}>
        {closeLabel != null && (
          <DialogCloseButton label={closeLabel} className={close.className} style={close.style} onClick={() => onClose?.()} />
        )}
