  { className, style, id, ...props },
  ref,
) {
  const bodyId = useDialogPart("body", id);
  const sx = rs(["rs-sheet-body", className], styles.body);
  return <p ref={ref} {...props} id={bodyId} className={sx.className} style={{ ...sx.style, ...style }} />;
});

