const styles = stylex.create({
  donut: {
    display: "block",
  },
  track: {
    fill: "none",
    stroke: vlak.divider,
    strokeWidth: 1,
  },
  value: {
    fill: "none",
    stroke: "var(--rs-chart-spot)",
    strokeWidth: 1,
    strokeLinecap: "butt",
  },
  /* Laid out in CSS px: the viewBox equals the rendered size, so type does not scale. */
  label: {
    fill: vlak.ink,
    fontSize: "1.25rem",
    fontWeight: 500,
    letterSpacing: "-0.03em",
    fontVariantNumeric: "tabular-nums",
