"use client";

import * as React from "react";
import * as stylex from "@stylexjs/stylex";
import { vlak, mq } from "./tokens.stylex";
import { rs } from "./rs";
import { Icon } from "./icons";

export interface CollapsibleProps
  extends Omit<React.DetailsHTMLAttributes<HTMLDetailsElement>, "title"> {
  title: React.ReactNode;
  defaultOpen?: boolean;
}

const styles = stylex.create({
  summary: {
    listStyle: "none",
    cursor: "pointer",
    display: "inline-flex",
    alignItems: "center",
    gap: "0.4375rem",
    minHeight: {
      default: vlak.hit,
      [mq.phone]: vlak.hit,
    },
    minWidth: vlak.hit,
    fontSize: {
      default: "0.84375rem",
      [mq.phone]: "1.0625rem",
    },
    fontWeight: 600,
    letterSpacing: "-0.01em",
    color: vlak.ink,
    "::-webkit-details-marker": {
      display: "none",
    },
    outlineWidth: {
      default: null,
      ":focus-visible": 2,
    },
    outlineStyle: {
      default: null,
      ":focus-visible": "solid",
    },
    outlineColor: {
      default: null,
      ":focus-visible": vlak.ink,
    },
    outlineOffset: {
      default: null,
      ":focus-visible": 2,
    },
  },
  chevron: {
    transition: {
      default: `transform ${vlak.duration} ${vlak.ease}`,
      [mq.reduce]: "none",
    },
  },
  chevronOpen: {
    transform: "rotate(180deg)",
  },
  body: {
    paddingTop: {
      default: "0.625rem",
      [mq.phone]: "0.75rem",
    },
    paddingInlineEnd: 0,
