      [mq.phone]: "1rem",
    },
  },
  th: {
    textAlign: {
      default: "start",
      ":last-child": "end",
    },
    fontWeight: 600,
    color: vlak.ink,
    letterSpacing: "-0.01em",
    paddingTop: {
      default: "0.625rem",
      [mq.phone]: "0.875rem",
    },
    paddingInlineEnd: {
      default: "1rem",
      [mq.phone]: "0.75rem",
      ":last-child": {
        default: 20,
        [mq.phone]: vlak.pad,
      },
    },
    paddingBottom: {
      default: "0.625rem",
      [mq.phone]: "0.875rem",
    },
    paddingInlineStart: {
      default: "0.75rem",
      [mq.phone]: "0.75rem",
      ":first-child": {
        default: 20,
        [mq.phone]: vlak.pad,
      },
    },
    borderBottomWidth: 2,
    borderBottomStyle: "solid",
    borderBottomColor: vlak.divider,
